import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';
import { CLERK_WORKSPACE, contentReady } from '../shell/helpers.ts';
import { DRAFTS_PATH, seedDrafts, type SeededDrafts } from '../product/outward-drafts-helpers.ts';

// `@visual` baselines for outward drafts (#737): the list, the editor, the diff view, a shared
// draft, Tamil and Kannada text, and the empty, denied, offline, error and loading states. Each
// runs in the 360/768/1280 light and dark projects. Baselines are only ever generated by the e2e
// workflow's `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md); until
// they exist each test skips. The relative "Prepared N ago" text follows the server clock: masked.
interface Shot {
  name: string;
  /** Path under the workspace, from the seeded draft ids. */
  path: (drafts: SeededDrafts) => string;
  seed: boolean;
  workspace?: string;
  diff?: boolean;
}

const NO_DRAFTS: SeededDrafts = { client: '', edited: '', shared: '', tamil: '', kannada: '' };

const SHOTS: Shot[] = [
  { name: 'list', seed: true, path: () => DRAFTS_PATH },
  { name: 'editor', seed: true, path: (d) => `${DRAFTS_PATH}?draft=${d.client}` },
  { name: 'diff', seed: true, diff: true, path: (d) => `${DRAFTS_PATH}?draft=${d.edited}` },
  { name: 'shared', seed: true, path: (d) => `${DRAFTS_PATH}?draft=${d.shared}` },
  { name: 'tamil', seed: true, path: (d) => `${DRAFTS_PATH}?draft=${d.tamil}` },
  { name: 'kannada', seed: true, path: (d) => `${DRAFTS_PATH}?draft=${d.kannada}` },
  { name: 'empty', seed: false, path: () => DRAFTS_PATH },
  { name: 'denied', seed: false, workspace: CLERK_WORKSPACE, path: () => DRAFTS_PATH },
  { name: 'offline', seed: false, path: () => `${DRAFTS_PATH}?__state=offline` },
  { name: 'error', seed: false, path: () => `${DRAFTS_PATH}?__state=error` },
  { name: 'loading', seed: false, path: () => `${DRAFTS_PATH}?__state=loading` },
];

for (const shot of SHOTS) {
  test(
    `outward-drafts ${shot.name}`,
    { tag: '@visual' },
    async ({ page, asUser, db }, testInfo) => {
      const baseline = testInfo.snapshotPath(`outward-drafts-${shot.name}.png`, {
        kind: 'screenshot',
      });
      test.skip(
        testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
        'no baseline yet: dispatch the e2e workflow with update_snapshots',
      );
      // The states are shown without drafts, so only the draft shots seed.
      const drafts = shot.seed ? await seedDrafts(db.name) : NO_DRAFTS;
      if (shot.workspace === undefined) {
        await asUser('owner', { path: shot.path(drafts) });
      } else {
        await asUser('owner');
        await page.goto(`/w/${shot.workspace}/${shot.path(drafts)}`);
      }
      if (shot.name === 'error') {
        await expect(page.locator('main').getByRole('alert')).toContainText(
          'Drafts could not be loaded',
          { timeout: 15_000 },
        );
      } else if (shot.name !== 'loading' && shot.name !== 'denied') {
        await contentReady(page);
      }
      if (shot.diff === true) {
        // The editor can stream in after <main> hydrates: retry until the toggle is pressed.
        const toggle = page.getByRole('button', { name: 'Compare with the prepared text' });
        const group = page.getByRole('group', { name: 'Changes from the prepared text' });
        await expect(async () => {
          if ((await toggle.getAttribute('aria-pressed')) !== 'true') await toggle.click();
          await expect(group).toBeVisible({ timeout: 1_000 });
        }).toPass();
      }
      await expect(page).toHaveScreenshot(`outward-drafts-${shot.name}.png`, {
        fullPage: true,
        animations: 'disabled',
        caret: 'hide',
        mask: [page.getByText(/^Prepared /)],
      });
    },
  );
}
